import{_ as o,o as r,c as t,a0 as s}from"./chunks/framework.CR-yHhk1.js";const m=JSON.parse('{"title":"Write a store driver","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/write-a-driver.md","filePath":"how-to/write-a-driver.md"}'),a={name:"how-to/write-a-driver.md"};function i(d,e,c,n,l,p){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="write-a-store-driver" tabindex="-1">Write a store driver <a class="header-anchor" href="#write-a-store-driver" aria-label="Permalink to &quot;Write a store driver&quot;">​</a></h1><p>This guide shows how to add a new agent&#39;s session store to sepia.</p><h2 id="the-shape" tabindex="-1">The shape <a class="header-anchor" href="#the-shape" aria-label="Permalink to &quot;The shape&quot;">​</a></h2><p>A driver is a standalone binary named <code>sepia-driver-&lt;id&gt;</code> that speaks ndjson JSON-RPC over stdio — the same framing <code>sepia serve</code> uses. It answers a <code>driver.manifest</code> handshake and the store ops it supports (<code>session.list</code>/<code>get</code>/<code>summary</code>/<code>history</code>, and optionally <code>session.save</code>/<code>rename</code>/<code>delete</code>, <code>session.rewind</code>, <code>config.read</code>/ <code>config.write</code> — see <a href="./../reference/protocol.html">the driver protocol</a>).</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p><strong>Model the store.</strong> Read the agent&#39;s on-disk format and map it onto the session IR (<code>sepia_core::Session</code>). Mark unrepresentable fields <code>lossy</code> in metadata rather than dropping them.</p></li><li><p><strong>Implement the ops.</strong> New drivers typically start from <code>crates/sepia-driver-cline</code> — it is the smallest complete example: <code>store.rs</code> (the repository), <code>cline.rs</code> (format mapping), <code>bin/sepia-driver-cline.rs</code> (the serve entry point + manifest).</p></li><li><p><strong>Declare a manifest.</strong> Name, version, protocol level, and the capability flags sepia uses to decide what a store supports (<code>sessionStore</code>, <code>sessionWrite</code>, <code>checkpoints</code>, <code>rewind</code>, <code>agentConfig</code> — see <a href="./../reference/protocol.html">the driver protocol</a>).</p></li><li><p><strong>Pass conformance.</strong> Point <code>sepia-testkit</code>&#39;s contract suite at your driver — it exercises the invariants every store must satisfy (round-trip listing, unknown-id behaviour, golden fixtures).</p></li><li><p><strong>Install.</strong> Drop the binary where discovery finds it: <code>$SEPIA_DRIVER_DIR</code> → the platform data dir (<code>$XDG_DATA_HOME/sepia/drivers</code> or <code>~/.local/share/sepia/drivers</code>) → <code>/usr/local/lib/sepia/drivers</code> → anywhere on <code>PATH</code>. <code>sepia driver list</code> shows what the plane can see (<code>--json</code> prints the probed manifests).</p></li></ol><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li>Blocking I/O (SQLite, file scans) runs on <code>spawn_blocking</code>.</li><li>One driver instance per store root — take the dir as an argument or <code>&lt;ID&gt;_DIR</code> env var (<code>SEPIA_CLINE_DIR</code> style).</li><li>Errors are <code>RpcError</code> with a <code>code</code>/<code>cause</code> payload — see <a href="./../reference/protocol.html">the protocol reference</a>.</li></ul>',8)])])}const v=o(a,[["render",i]]);export{m as __pageData,v as default};
